/** One local attack timeline on the logical server. Rendering never causes hits or spawns. */
public final class EarthSpirit extends Monster {
    public String lastDamageReport="No registered hit against a player yet";
    private static final EntityDataAccessor<Integer> STATE=SynchedEntityData.defineId(EarthSpirit.class,EntityDataSerializers.INT),PHASE=SynchedEntityData.defineId(EarthSpirit.class,EntityDataSerializers.INT),PILLAR=SynchedEntityData.defineId(EarthSpirit.class,EntityDataSerializers.INT),PENDING=SynchedEntityData.defineId(EarthSpirit.class,EntityDataSerializers.INT),ARMOR=SynchedEntityData.defineId(EarthSpirit.class,EntityDataSerializers.INT);
    private static final EntityDataAccessor<BlockPos> PILLAR_POS=SynchedEntityData.defineId(EarthSpirit.class,EntityDataSerializers.BLOCK_POS);
    private static final EntityDataAccessor<Integer> TOTAL=SynchedEntityData.defineId(EarthSpirit.class,EntityDataSerializers.INT);
    private static final EntityDataAccessor<Long> START=SynchedEntityData.defineId(EarthSpirit.class,EntityDataSerializers.LONG);
    private final ServerBossEvent bar=new ServerBossEvent(net.minecraft.network.chat.Component.translatable("entity.slavicmyths.earth_spirit"),BossEvent.BossBarColor.YELLOW,BossEvent.BossBarOverlay.PROGRESS);
    private UUID arena;private BlockPos home;private final EnumMap<Action,Integer> cooldowns=new EnumMap<>(Action.class);
    private int elapsed,duration,absent,summonIn=EarthRules.INTERVAL,attackId,ambientIn=300,walkTick,armorIn;private Action lastHeavy=Action.IDLE;
    private Vec3 aim=Vec3.ZERO;private final Map<UUID,Integer> pressure=new HashMap<>(),meleeLast=new HashMap<>();private final List<UUID> servants=new ArrayList<>();private List<BlockPos> spawnPoints=List.of();private boolean legitimate;private final Set<UUID> participants=new HashSet<>();
    public EarthSpirit(EntityType<? extends Monster> t,Level w){super(t,w);setPersistenceRequired();xpReward=80;getAttribute(Attributes.MAX_HEALTH).setBaseValue(EarthRules.HEALTH);setHealth((float)EarthRules.HEALTH);getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(EarthRules.SPEED);}
    @Override protected void defineSynchedData(SynchedEntityData.Builder b){super.defineSynchedData(b);b.define(STATE,Action.IDLE.ordinal());b.define(PHASE,1);b.define(PILLAR,-1);b.define(PENDING,0);b.define(ARMOR,0);b.define(TOTAL,4);b.define(PILLAR_POS,BlockPos.ZERO);b.define(START,0L);}
    public Action action(){return Action.values()[entityData.get(STATE)];}public int phase(){return entityData.get(PHASE);}public BlockPos pillarOrigin(){return entityData.get(PILLAR_POS);}public int volleyTotal(){return entityData.get(TOTAL);}public int pending(){return entityData.get(PENDING);}public int pillar(){return entityData.get(PILLAR);}public int armorTicks(){return entityData.get(ARMOR);}public float age(float partial){return (float)(level().getGameTime()-entityData.get(START))+partial;}
    public net.minecraft.world.damagesource.DamageSource attackSource(Entity direct){var key=net.minecraft.resources.ResourceKey.create(net.minecraft.core.registries.Registries.DAMAGE_TYPE,EarthContent.id(direct instanceof EarthActor actor&&(actor.kind()==EarthActor.STONE||actor.kind()==EarthActor.PILLAR)?"earth_projectile":"earth_strike"));return new net.minecraft.world.damagesource.DamageSource(level().registryAccess().registryOrThrow(net.minecraft.core.registries.Registries.DAMAGE_TYPE).getHolderOrThrow(key),direct,this);}
    public UUID arenaId(){return arena;}public BlockPos home(){return home==null?blockPosition():home;}public void servantDied(UUID id){servants.remove(id);}
    public EarthArena.Entry entry(){return arena!=null&&level() instanceof ServerLevel w?EarthArena.get(w).entries.get(arena):null;}
    public void bind(UUID arena,BlockPos home){this.arena=arena;this.home=home.immutable();restrictTo(home,19);}
    public void addParticipant(Player player){if(valid(player))participants.add(player.getUUID());}
    public void awaken(){begin(Action.AWAKEN,EarthRules.INTRO);}
    @Override protected void registerGoals(){goalSelector.addGoal(1,new Goal(){ {setFlags(EnumSet.of(Flag.MOVE,Flag.LOOK));}public boolean canUse(){return isAlive();}public void tick(){if(action()==Action.APPROACH){var e=entry();if(e!=null){Vec3 column=e.pillar(pillar()).getCenter().add(.5,0,.5);Vec3 inward=e.center.getCenter().subtract(column).multiply(1,0,1).normalize();Vec3 p=column.add(inward.scale(3.6));getLookControl().setLookAt(column.x,column.y+3,column.z,15,15);getNavigation().moveTo(p.x,e.center.getY(),p.z,1);}return;}if(action()!=Action.IDLE||!valid(getTarget())){getNavigation().stop();return;}getLookControl().setLookAt(getTarget(),12,12);getNavigation().moveTo(getTarget(),1);}});}
    public boolean valid(LivingEntity t){return t instanceof Player p&&p.isAlive()&&!p.isCreative()&&!p.isSpectator()&&p.level()==level()&&inside(p.position());}
    public boolean inside(Vec3 p){var e=entry();return e!=null?e.contains(p):Math.abs(p.y-home().getY())<8&&p.distanceToSqr(home().getCenter())<19*19;}
    @Override public boolean isAlliedTo(Entity e){return e instanceof EarthSpirit||e instanceof EarthServant||super.isAlliedTo(e);}
    @Override public boolean canBeAffected(MobEffectInstance e){return e.getEffect().value()!=ModEffects.CUT.get()&&e.getEffect().value()!=ModEffects.RARE_BLEED.get()&&e.getEffect().value()!=ModEffects.WOLF_CUT.get()&&super.canBeAffected(e);}
    @Override public boolean hurt(DamageSource s,float amount){if(action()==Action.AWAKEN&&!s.is(DamageTypeTags.BYPASSES_INVULNERABILITY)||s.is(DamageTypes.FALL)||s.is(DamageTypes.IN_WALL)||s.getEntity() instanceof EarthServant||s.getEntity()==this)return false;boolean result=super.hurt(s,amount);return result;}
    public void registeredHit(DamageSource source,float actual){if(actual<=0)return;if(source.getEntity() instanceof Player p&&valid(p)){participants.add(p.getUUID());setTarget(p);getLookControl().setLookAt(p,35,25);if(action()==Action.APPROACH)begin(Action.RECOVER,8);}if(source.is(DamageTypes.PLAYER_ATTACK)&&source.getDirectEntity() instanceof Player p&&valid(p))meleeLast.put(p.getUUID(),tickCount);}
    public float armorMultiplier(DamageSource source){return armorIn>0?(source.is(DamageTypeTags.IS_PROJECTILE)||source.getDirectEntity()!=source.getEntity()?.75F:.90F):1;}
    private boolean ready(Action a){return cooldowns.getOrDefault(a,0)==0;}
    private void begin(Action a,int ticks){entityData.set(STATE,a.ordinal());entityData.set(START,level().getGameTime());elapsed=0;duration=ticks;if(a==Action.MELEE)cooldowns.put(a,a.cooldown);attackId++;getNavigation().stop();aim=valid(getTarget())?getTarget().position():position().add(getLookAngle().scale(8));}
    private void finish(){Action a=action();if(a!=Action.MELEE&&a!=Action.PHASE&&a!=Action.AWAKEN&&a!=Action.APPROACH)cooldowns.put(a,(int)(a.cooldown*(phase()==3&&(a==Action.VOLLEY||a==Action.TREMOR)?.9:1)));if(a!=Action.MELEE&&a!=Action.RECOVER&&a!=Action.PHASE)lastHeavy=a;entityData.set(PENDING,0);entityData.set(PILLAR,-1);begin(Action.RECOVER,a==Action.MELEE?6:EarthRules.HEAVY_GAP);}
    private void cue(String s){if(level() instanceof ServerLevel w)EarthArena.cue(w,blockPosition(),s,.8F);}
    @Override public void aiStep(){super.aiStep();if(level().isClientSide||!isAlive())return;if(home==null){home=blockPosition();restrictTo(home,19);}var w=(ServerLevel)level();var e=entry();
        if(valid(getTarget())&&action()!=Action.APPROACH&&action()!=Action.AWAKEN&&action()!=Action.DORMANT){Vec3 focus=action()==Action.IDLE||action()==Action.RECOVER?getTarget().position():aim;double dx=focus.x-getX(),dz=focus.z-getZ();float yaw=(float)(Math.atan2(dz,dx)*180/Math.PI)-90;setYRot(net.minecraft.util.Mth.rotLerp(.3F,getYRot(),yaw));yBodyRot=getYRot();getLookControl().setLookAt(getTarget(),35,25);}
        if(tickCount%10==0){var choices=w.getEntitiesOfClass(Player.class,new AABB(home).inflate(19,8,19),this::valid);if(!valid(getTarget()))setTarget(choices.stream().min(Comparator.comparingDouble(this::distanceToSqr)).orElse(null));if(choices.isEmpty())absent+=10;else absent=0;}
        if(absent>=EarthRules.DORMANT_AFTER&&action()!=Action.AWAKEN){if(action()!=Action.DORMANT){cancelActors();armorIn=0;entityData.set(ARMOR,0);begin(Action.DORMANT,0);if(e!=null){e.state=EarthArena.State.DORMANT;EarthArena.open(w,e);}}bar.setVisible(false);return;}
        if(action()==Action.DORMANT){if(!valid(getTarget()))return;summonIn=Math.max(40,summonIn);begin(Action.RECOVER,40);if(e!=null){e.state=EarthArena.State.ACTIVE;EarthArena.get(w).setDirty();}}
        cooldowns.replaceAll((a,n)->Math.max(0,n-1));if(armorIn>0){armorIn--;entityData.set(ARMOR,armorIn);if(armorIn==14)cue("pillar_rip");}if(action()!=Action.AWAKEN)summonIn=Math.max(0,summonIn-1);
        if(e!=null&&(e.state==EarthArena.State.ACTIVE||action()==Action.AWAKEN&&elapsed>=16))EarthArena.gateTick(w,e);
        bar.setProgress(Math.clamp(getHealth()/getMaxHealth(),0,1));bar.setVisible(action()!=Action.AWAKEN&&action()!=Action.DORMANT);bar.setName(net.minecraft.network.chat.Component.translatable("earth.slavicmyths.boss_phase",getDisplayName(),phase()));
        pressure.replaceAll((id,n)->{var p=w.getServer().getPlayerList().getPlayer(id);return p!=null&&valid(p)&&surfaceDistance(p)<=4.5&&tickCount-meleeLast.getOrDefault(id,-1000)<=30?Math.min(EarthRules.PRESSURE,n+1):Math.max(0,n-2);});for(var id:meleeLast.keySet())pressure.putIfAbsent(id,1);
        if(action()==Action.IDLE){int wanted=EarthRules.phase(getHealth(),getMaxHealth());if(wanted>phase()){entityData.set(PHASE,phase()+1);begin(Action.PHASE,phase()==3?50:40);cue("phase_change");return;}
            if(!inside(position())){getNavigation().moveTo(home.getX()+.5,home.getY(),home.getZ()+.5,1);return;}if(valid(getTarget()))choose();
            if(--ambientIn<=0){cue(random.nextBoolean()?"ambient_1":"ambient_2");ambientIn=260+random.nextInt(141);}if(getDeltaMovement().horizontalDistanceSqr()>.0001&&++walkTick%16==0)cue(walkTick%32==0?"footstep_1":"footstep_2");
        }else {elapsed++;step();if(elapsed>=duration&&action()!=Action.IDLE&&action()!=Action.DORMANT){if(action()==Action.RECOVER)begin(Action.IDLE,0);else finish();}}
    }
    private double surfaceDistance(LivingEntity p){var box=getBoundingBox();double x=Math.max(box.minX,Math.min(box.maxX,p.getX())),z=Math.max(box.minZ,Math.min(box.maxZ,p.getZ()));return Math.hypot(p.getX()-x,p.getZ()-z);}
    private void choose(){var w=(ServerLevel)level();var t=getTarget();double d=distanceTo(t);
        if(surfaceDistance(t)<=4.4&&ready(Action.MELEE)&&hasLineOfSight(t)){begin(Action.MELEE,24);cue("melee_windup");return;}
        if(summonIn==0){servants.removeIf(id->{var entity=w.getEntity(id);return entity!=null&&!entity.isAlive();});if(servants.size()<=3){spawnPoints=planSummons(w);if(EarthRules.canSummon(servants.size(),spawnPoints.size())){begin(Action.SUMMON,44);cue("summon_warning");for(var at:spawnPoints)EarthActor.marker(w,this,at.getCenter().add(0,-.45,0),1,44);return;}}summonIn=EarthRules.INTERVAL;}
        if(ready(Action.COUNTER)&&pressure.values().stream().anyMatch(n->n>=EarthRules.PRESSURE)){begin(Action.COUNTER,50);EarthActor.marker(w,this,position(),6.5,26);return;}
        var options=new ArrayList<Action>();var e=entry();int selected=-1;if(e!=null&&d>=9&&d<=28&&ready(Action.PILLAR)){for(int i=0;i<5;i++)if(EarthArena.available(w,e,i)&&(selected==-1||e.pillar(i).distSqr(blockPosition())<e.pillar(selected).distSqr(blockPosition())))selected=i;if(selected>=0)options.add(Action.PILLAR);}
        if(d>=4.5&&d<=30&&hasLineOfSight(t)&&ready(Action.VOLLEY))options.add(Action.VOLLEY);if(d<15&&ready(Action.TREMOR))options.add(Action.TREMOR);if(phase()>1&&d<16&&ready(Action.SPIKES))options.add(Action.SPIKES);if(phase()>1&&ready(Action.ARMOR)&&armorIn==0)options.add(Action.ARMOR);
        if(options.size()>1)options.remove(lastHeavy);if(!options.isEmpty()){Action a=options.get(random.nextInt(options.size()));if(a==Action.PILLAR){entityData.set(PILLAR,selected);begin(Action.APPROACH,100);}else{begin(a,a==Action.VOLLEY?26+(EarthRules.VOLLEY_MAX-1)*EarthRules.SHOT_INTERVAL+16:a.duration);if(a==Action.VOLLEY){int count=4+random.nextInt(3);entityData.set(PENDING,count);entityData.set(TOTAL,count);duration=26+(count-1)*EarthRules.SHOT_INTERVAL+16;cue("volley_charge");}if(a==Action.TREMOR)EarthActor.marker(w,this,position(),11,33);if(a==Action.SPIKES)EarthActor.line(w,this,aim.subtract(position()),true);if(a==Action.ARMOR)cue("armor_activate");}return;}
        if(surfaceDistance(t)<=4.4&&ready(Action.MELEE)&&hasLineOfSight(t)){begin(Action.MELEE,24);cue("melee_windup");}
    }
    private void step(){var w=(ServerLevel)level();var e=entry();switch(action()){
        case AWAKEN->{if(elapsed==8)cue("awaken_rumble");if(e!=null&&elapsed==16)w.setBlock(e.center,EarthContent.SEAL.get().defaultBlockState().setValue(EarthSeal.CRACK,2),3);if(e!=null&&elapsed==24)w.setBlock(e.center,Blocks.AIR.defaultBlockState(),3);if(elapsed==80)cue("roar_1");if(elapsed==88){if(e!=null){e.state=EarthArena.State.ACTIVE;EarthArena.get(w).setDirty();}summonIn=EarthRules.INTERVAL;}}
        case APPROACH->{if(e==null||!EarthArena.available(w,e,pillar())){finish();return;}if(e.pillar(pillar()).distSqr(blockPosition())<=20){entityData.set(PILLAR_POS,e.pillar(pillar()));begin(Action.PILLAR,76);}else if(elapsed>=100)finish();}
        case PILLAR->{if(elapsed==12)cue("pillar_grip");if(elapsed==20){if(e==null||!EarthArena.consume(w,e,pillar())){finish();return;}cue("pillar_rip");EarthActor.held(w,this,e.pillar(pillar()).getCenter().add(.5,2.5,.5));}if(elapsed==46){cue("pillar_throw");EarthActor.projectile(w,this,hand(),predicted(7),true);}}
        case VOLLEY->{if(elapsed>=26&&(elapsed-26)%EarthRules.SHOT_INTERVAL==0&&pending()>0){EarthActor.projectile(w,this,hand(),predicted(5),false);entityData.set(PENDING,pending()-1);cue("volley_release");}}
        case COUNTER->{if(elapsed==6)cue("melee_windup");if(elapsed==26){cue("melee_impact");cue("shockwave");EarthActor.wave(w,this,6.5,9,false);pressure.clear();}}
        case TREMOR->{if(elapsed==6)cue("tremor_warning");if(elapsed==33){cue("tremor_impact");EarthActor.wave(w,this,11,16,true);}}
        case MELEE->{if(elapsed==12){cue("melee_impact");Vec3 forward=aim.subtract(position()).multiply(1,0,1).normalize();for(var p:w.getEntitiesOfClass(Player.class,getBoundingBox().inflate(4.4,0,4.4),this::valid)){Vec3 v=p.position().subtract(position()).multiply(1,0,1).normalize();if(surfaceDistance(p)<=4.4&&v.dot(forward)>=Math.cos(Math.toRadians(50))&&hasLineOfSight(p))p.hurt(attackSource(this),EarthRules.MELEE_RAW);}}}
        case SUMMON->{if(elapsed==24){var wave=new ArrayList<EarthServant>();boolean safe=spawnPoints.size()==3;for(var at:spawnPoints)if(!safeSpawn(w,at))safe=false;if(safe)for(var at:spawnPoints){var s=EarthContent.SERVANT.get().create(w);if(s==null){safe=false;break;}s.moveTo(at.getX()+.5,at.getY(),at.getZ()+.5,0,0);s.bind(getUUID(),arena,home());if(!w.addFreshEntity(s)){safe=false;break;}wave.add(s);}if(!safe)wave.forEach(Entity::discard);else{wave.forEach(s->servants.add(s.getUUID()));EarthArena.cue(w,spawnPoints.getFirst(),"servant_emerge",.55F);}}if(elapsed==44)summonIn=EarthRules.INTERVAL;}
        case SPIKES->{if(elapsed==6)cue("tremor_warning");if(elapsed==24){EarthActor.line(w,this,aim.subtract(position()),false);cue("volley_impact");}}
        case ARMOR->{if(elapsed==20){armorIn=EarthRules.ARMOR_DURATION;entityData.set(ARMOR,armorIn);}}
        case PHASE->{if(elapsed==22)cue("roar_2");if(elapsed==1&&phase()==3)getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(EarthRules.SPEED*1.08);}
        default->{}
    }}
    public Vec3 hand(){var at=EarthRules.hand(action(),age(0),volleyTotal(),yBodyRot,(float)Math.sin(tickCount*.045)*.55F,getScale());return position().add(at.x(),at.y(),at.z());}
    private Vec3 predicted(int ticks){var t=getTarget();return valid(t)?t.position().add(0,.7,0).add(t.getDeltaMovement().multiply(ticks,0,ticks)):aim.add(0,.7,0);}
    private List<BlockPos> planSummons(ServerLevel w){var points=new ArrayList<BlockPos>();for(int i=0;i<12&&points.size()<3;i++){double a=i*Math.PI*2/12+random.nextDouble()*.2;var p=BlockPos.containing(getX()+Math.cos(a)*8,getY(),getZ()+Math.sin(a)*8);if(safeSpawn(w,p)&&points.stream().allMatch(q->q.distSqr(p)>=9))points.add(p);}return List.copyOf(points);}
    private boolean safeSpawn(ServerLevel w,BlockPos p){if(!inside(p.getCenter())||!w.hasChunkAt(p)||!w.getBlockState(p.below()).isCollisionShapeFullBlock(w,p.below()))return false;var box=new AABB(p.getX()+.05,p.getY(),p.getZ()+.05,p.getX()+.95,p.getY()+1.5,p.getZ()+.95);return w.noCollision(box)&&w.getEntitiesOfClass(Player.class,box.inflate(3),Player::isAlive).isEmpty()&&w.getEntitiesOfClass(EarthServant.class,box.inflate(1)).isEmpty();}
    private void cancelActors(){if(level() instanceof ServerLevel w)for(var actor:w.getEntitiesOfClass(EarthActor.class,getBoundingBox().inflate(40),a->getUUID().equals(a.owner())))actor.discard();entityData.set(PENDING,0);entityData.set(PILLAR,-1);}
    @Override public void die(DamageSource source){if(source.getEntity() instanceof Player p&&valid(p))participants.add(p.getUUID());legitimate=!source.is(DamageTypeTags.BYPASSES_INVULNERABILITY)&&!participants.isEmpty()&&!(source.getEntity() instanceof Player p&&(p.isCreative()||p.isSpectator()));if(!legitimate)xpReward=0;bar.removeAllPlayers();cancelActors();armorIn=0;begin(Action.DEATH,EarthRules.DEATH);if(level() instanceof ServerLevel w){var e=entry();if(e!=null)EarthArena.defeat(w,e,true);for(var id:servants)if(w.getEntity(id) instanceof EarthServant s)s.collapse();}if(legitimate&&level() instanceof ServerLevel w)for(var id:participants){var p=w.getServer().getPlayerList().getPlayer(id);if(p!=null)org.slavicmyths.progression.Knowledge.award(p,"earth_heart");}super.die(source);cue("death_fall");}
    @Override protected void tickDeath(){deathTime++;if(level() instanceof ServerLevel w){if(deathTime==16)EarthActor.collapse(w,position().add(0,5.8,0),8,.7);if(deathTime==28)EarthActor.collapse(w,position().add(0,3.6,0),12,1.4);if(deathTime==44)EarthActor.collapse(w,position().add(0,4.1,0),14,.85);if(deathTime==60)EarthActor.collapse(w,position().add(0,2.2,0),12,.7);if(deathTime==78)EarthActor.collapse(w,position().add(0,.8,0),12,.8);}if(deathTime>=EarthRules.DEATH&&!level().isClientSide)remove(RemovalReason.KILLED);}
    @Override public void startSeenByPlayer(ServerPlayer p){super.startSeenByPlayer(p);bar.addPlayer(p);}@Override public void stopSeenByPlayer(ServerPlayer p){super.stopSeenByPlayer(p);bar.removePlayer(p);}@Override public void remove(RemovalReason r){bar.removeAllPlayers();super.remove(r);}
    @Override protected void dropCustomDeathLoot(ServerLevel w,DamageSource s,boolean hit){super.dropCustomDeathLoot(w,s,hit);if(arena==null)spawnAtLocation(EarthContent.RUNE.get());}
    @Override protected boolean shouldDropLoot(){return super.shouldDropLoot();}
    @Override protected net.minecraft.sounds.SoundEvent getDeathSound(){return null;}@Override protected net.minecraft.sounds.SoundEvent getHurtSound(DamageSource s){return null;}
    @Override public void addAdditionalSaveData(CompoundTag n){super.addAdditionalSaveData(n);if(arena!=null)n.putUUID("EarthArena",arena);n.putLong("EarthHome",home().asLong());n.putInt("EarthPhase",phase());n.putInt("EarthSummonIn",summonIn);n.putString("EarthAction",action().name());n.putInt("EarthElapsed",elapsed);n.putInt("EarthAttackId",attackId);n.putString("EarthLastHeavy",lastHeavy.name());n.putInt("EarthAbsent",absent);var c=new CompoundTag();cooldowns.forEach((a,v)->c.putInt(a.name(),v));n.put("EarthCooldowns",c);var list=new ListTag();for(var id:servants)list.add(NbtUtils.createUUID(id));n.put("EarthServants",list);var members=new ListTag();for(var id:participants)members.add(NbtUtils.createUUID(id));n.put("EarthParticipants",members);}
    @Override public void readAdditionalSaveData(CompoundTag n){super.readAdditionalSaveData(n);if(n.hasUUID("EarthArena"))arena=n.getUUID("EarthArena");home=BlockPos.of(n.getLong("EarthHome"));restrictTo(home,19);entityData.set(PHASE,Math.clamp(n.getInt("EarthPhase"),1,3));summonIn=Math.clamp(n.getInt("EarthSummonIn"),40,EarthRules.INTERVAL);attackId=n.getInt("EarthAttackId");absent=n.getInt("EarthAbsent");for(var a:Action.values())cooldowns.put(a,Math.max(0,n.getCompound("EarthCooldowns").getInt(a.name())));for(var t:n.getList("EarthServants",Tag.TAG_INT_ARRAY))servants.add(NbtUtils.loadUUID(t));try{lastHeavy=Action.valueOf(n.getString("EarthLastHeavy"));}catch(IllegalArgumentException ignored){}for(var t:n.getList("EarthParticipants",Tag.TAG_INT_ARRAY))participants.add(NbtUtils.loadUUID(t));if(phase()==3)getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(EarthRules.SPEED*1.08);var e=entry();if(e!=null){servants.removeAll(e.retired);e.retired.clear();EarthArena.get((ServerLevel)level()).setDirty();}if(e!=null&&!e.gateClosed)e.gateStart=0;String saved=n.getString("EarthAction");if(saved.equals("AWAKEN")){begin(Action.AWAKEN,88);elapsed=Math.clamp(n.getInt("EarthElapsed"),0,87);entityData.set(START,level().getGameTime()-elapsed);}else if(saved.equals("DORMANT"))begin(Action.DORMANT,0);else begin(Action.RECOVER,40);}
}
